cssCode:
.sparkle {
  position: absolute; width: 8px; height: 8px;
  background: radial-gradient(circle, #fff 10%, #d4af37 60%, transparent 100%);
  border-radius: 50%; pointer-events: none;
  box-shadow: 0 0 10px #d4af37;
  animation: sparkleFade 1s forwards ease-out;
  transform: translate(-50%, -50%);
}
@keyframes sparkleFade {
  0% { transform: translate(-50%, -50%) scale(1) rotate(0deg); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(0) rotate(180deg); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;touch-action:none;';

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const spark = document.createElement('div');
  spark.className = 'sparkle';
  spark.style.left = `${e.clientX - rect.left}px`;
  spark.style.top = `${e.clientY - rect.top}px`;
  c.appendChild(spark);
  setTimeout(() => spark.remove(), 1000);
});
